c.cpp:
class Solution {
public:
    int countDistinctIntegers(vector<int>& nums) {
        unordered_set<int> st(nums.begin(), nums.end());
        for (int x : nums) {
            long long r = 0;
            while (x) { r = r * 10 + x % 10; x /= 10; }
            st.insert((int)r);
        }
        return st.size();
    }
};

