class Solution {
    public int countDistinctIntegers(int[] nums) {
        Set<Integer> st = new HashSet<>();
        for (int x : nums) {
            st.add(x);
            int r = 0;
            while (x > 0) { r = r * 10 + x % 10; x /= 10; }
            st.add(r);
        }
        return st.size();
    }
}

