var countDistinctIntegers = function(nums) {
    const st = new Set();
    const rev = x => { let r = 0; while (x > 0) { r = r * 10 + x % 10; x = Math.floor(x / 10); } return r; };
    for (const x of nums) { st.add(x); st.add(rev(x)); }
    return st.size();
};

